declaration:
FUNCTION_BLOCK FB

VAR_INPUT

  ManualMode : BOOL;             
  SingleStepMode : BOOL;         
  SingleCycleMode : BOOL;        
  ContinuousMode : BOOL;         
  EmergencyStop : BOOL;          
  Start : BOOL;                  
  DownButton : BOOL;             
  UpButton : BOOL;               
  LeftButton : BOOL;             
  RightButton : BOOL;            
  GripButton : BOOL;             
  ReleaseButton : BOOL;          
  DownLimitSwitch : BOOL;        
  UpLimitSwitch : BOOL;
  LeftLimitSwitch : BOOL;
  RightLimitSwitch : BOOL;
  GripLimitSwitch : BOOL;        
  ReleaseLimitSwitch : BOOL;     
END_VAR
VAR_OUTPUT
  MoveDown : BOOL;
  MoveUp : BOOL;
  MoveLeft : BOOL;
  MoveRight : BOOL;
  ActivateGrip : BOOL;
  ActivateRelease : BOOL;
END_VAR
VAR
  startEdge : BOOL;              
  startPrev : BOOL;
  modeNow : INT;                 
  modePrev : INT;
  fsStep : INT;                  
  fsActive : BOOL;               
  fsDone : BOOL;                 
  guard : INT;                   
END_VAR

implementation:
MoveDown := FALSE;
MoveUp := FALSE;
MoveLeft := FALSE;
MoveRight := FALSE;
ActivateGrip := FALSE;
ActivateRelease := FALSE;


startEdge := Start AND NOT startPrev;
startPrev := Start;


modeNow := 0;
IF ContinuousMode THEN
  modeNow := 4;
END_IF
IF SingleCycleMode THEN
  modeNow := 3;
END_IF
IF SingleStepMode THEN
  modeNow := 2;
END_IF
IF ManualMode THEN
  modeNow := 1;
END_IF


IF modeNow <> modePrev THEN
  fsActive := FALSE;
  fsStep := 0;
  fsDone := FALSE;
END_IF
modePrev := modeNow;

IF NOT EmergencyStop THEN

  fsDone := FALSE;
ELSIF modeNow = 1 THEN

  IF DownButton AND (NOT DownLimitSwitch) AND (NOT UpButton) THEN
    MoveDown := TRUE;
  END_IF
  IF UpButton AND (NOT UpLimitSwitch) AND (NOT DownButton) THEN
    MoveUp := TRUE;
  END_IF
  IF LeftButton AND (NOT LeftLimitSwitch) AND (NOT RightButton) THEN
    MoveLeft := TRUE;
  END_IF
  IF RightButton AND (NOT RightLimitSwitch) AND (NOT LeftButton) THEN
    MoveRight := TRUE;
  END_IF
  IF GripButton AND (NOT GripLimitSwitch) AND (NOT ReleaseButton) THEN
    ActivateGrip := TRUE;
  END_IF
  IF ReleaseButton AND (NOT ReleaseLimitSwitch) AND (NOT GripButton) THEN
    ActivateRelease := TRUE;
  END_IF
ELSIF (modeNow = 2) OR (modeNow = 3) OR (modeNow = 4) THEN

  IF startEdge AND (NOT fsActive) THEN
    IF modeNow = 2 THEN

      IF fsStep < 1 THEN
        fsStep := 1;
      END_IF
    ELSE

      fsStep := 1;
    END_IF
    fsActive := TRUE;
  END_IF

  guard := 0;
  WHILE fsActive AND (guard < 8) DO
    guard := guard + 1;
    fsDone := FALSE;

    IF fsStep = 1 THEN
      IF DownLimitSwitch THEN fsDone := TRUE; ELSE MoveDown := TRUE; END_IF
    ELSIF fsStep = 2 THEN
      IF GripLimitSwitch THEN fsDone := TRUE; ELSE ActivateGrip := TRUE; END_IF
    ELSIF fsStep = 3 THEN
      IF UpLimitSwitch THEN fsDone := TRUE; ELSE MoveUp := TRUE; END_IF
    ELSIF fsStep = 4 THEN
      IF RightLimitSwitch THEN fsDone := TRUE; ELSE MoveRight := TRUE; END_IF
    ELSIF fsStep = 5 THEN
      IF DownLimitSwitch THEN fsDone := TRUE; ELSE MoveDown := TRUE; END_IF
    ELSIF fsStep = 6 THEN
      IF ReleaseLimitSwitch THEN fsDone := TRUE; ELSE ActivateRelease := TRUE; END_IF
    ELSIF fsStep = 7 THEN
      IF UpLimitSwitch THEN fsDone := TRUE; ELSE MoveUp := TRUE; END_IF
    ELSE
      IF LeftLimitSwitch THEN fsDone := TRUE; ELSE MoveLeft := TRUE; END_IF
    END_IF

    IF NOT fsDone THEN

      guard := 8;
    ELSIF modeNow = 4 THEN

      fsStep := fsStep + 1;
      IF fsStep > 8 THEN
        fsStep := 1;
      END_IF
    ELSIF modeNow = 3 THEN

      IF fsStep >= 8 THEN
        fsActive := FALSE;
        fsStep := 0;
      ELSE
        fsStep := fsStep + 1;
      END_IF
    ELSE

      fsActive := FALSE;
      fsStep := fsStep + 1;
      IF fsStep > 8 THEN
        fsStep := 1;
      END_IF
    END_IF
  END_WHILE
END_IF
